mapper.select:
SELECT mm.id, mm.mv_name, mm.music_id, m.music_name, mm.musician_id, mu.stage_name, mm.duration, mm.cover_url, mm.mv_url, mm.release_time, mm.play_count, mm.like_count, mm.comment_count, mm.share_count, mm.is_vip, mm.status, mvr.quality_type, mvr.mv_url as quality_mv_url, mvr.file_size, mvr.is_vip_limit FROM music_mv mm LEFT JOIN music m ON mm.music_id = m.id LEFT JOIN musician mu ON mm.musician_id = mu.id LEFT JOIN mv_quality_relation mvr ON mm.id = mvr.mv_id WHERE mm.id IN
#{mvId}
AND mm.status = 1

mapper.update:
UPDATE music_mv
SET play_count = play_count + #{increment}
WHERE id = #{mvId}

UPDATE music_mv
SET like_count = like_count + 1
WHERE id = #{mvId}

UPDATE music_mv
SET collection_count = collection_count + 1
WHERE id = #{mvId}
